CREATE TABLE quizzes(id UUID PRIMARY KEY,title VARCHAR(160) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PUBLISHED',daily BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE quiz_questions(id UUID PRIMARY KEY,quiz_id UUID NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,prompt TEXT NOT NULL,options TEXT NOT NULL,correct_index INTEGER NOT NULL,hint TEXT NOT NULL);
CREATE TABLE quiz_attempts(id UUID PRIMARY KEY,quiz_id UUID NOT NULL REFERENCES quizzes(id),user_id UUID NOT NULL,status VARCHAR(16) NOT NULL,score INTEGER,hints_used INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
